eThreadsMenuHelp,4,			kSimpleThreadsMenuHelp,4,		},		// Third Item		HMStringResItem 		{			kSimpleThreadsMenuHelp,5,			kSimpleThreadsMenuHelp,5,			kSimpleThreadsMenuHelp,5,			kSimpleThreadsMenuHelp,5,		},	}};#endif // !qCarbon//--------------------------------------------------------------------------------------------------// RESOURCES FOR VIEWS, DIALOGS, ALERTS etc. //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// Views //--------------------------------------------------------------------------------------------------#ifndef MW_Rezinclude "SimpleThreads.view" not 'vers';#endif/*resource 'STR#' (kSimpleThreadsWindowTitles,#if qNames"Window titles",#endifpurgeable) {	{	""	}};resource 'STR#' (1200,purgeable) {	{	""	}};resource 'TxSt' (1200, purgeable) {	tsBold,	10,	black,	"Geneva"};resource 'TxSt' (kSystemTextStyle, purgeable) {tsPlain, 0, black, ""};*//*resource 'View' (kSimpleThreadsWindowID,#if qNames"kSimpleThreadsWindowID",#endifpurgeable) { MAThreeOh, 	{	ViewSignatureAndClassname		{'wind', 534, "", 'WIND', enabled, noIdle, {}, MAThreeOh, 		{50, 20}, {335, 215}, sizeVariable, sizeVariable, shown, doesntWantToBeTarget, 		handlesCursor, letsSubViewsHandleCursor, noCursorID, 		handlesHelp, letsSubViewsHandleHelp, noHelpID, 1, 		NoDrawingEnvironment {}, 		AdornerListSignatureAndClassname {NoIdentifier, AdornerList, AdornerElementSize, AdornerElementSizeShift, DynamicArrayAllocationIncrement, {			AdornFirst, AdornerLocalObject {EraseAdorner}, 			DrawView, AdornerLocalObject {DrawAdorner}, 			AdornLast, AdornerLocalObject {ResizeIconAdorner}}}, emptyUserArea, 		Window {zoomDocProc, 'THR1', goAwayBox, resizable, ignoreFirstClick, 			freeOnClosing, disposeOnFree, closesDocument, openWithDocument, dontAdaptToScreen, stagger, forceOnScreen, 			do