,	reserved,	reserved,		/* Suggested partition size */	(10000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif//--------------------------------------------------------------------------------------------------// Icons//--------------------------------------------------------------------------------------------------include kDefaultRsrcName  'ICN#' (kApplicationID);	// MacApp Family large black & white	include kDefaultRsrcName  'ICN#' (kDocumentID);		// MacApp Document large black & whiteinclude kDefaultRsrcName  'ICN#' (kStationeryID);	// MacApp Stationery large black & white	include kDefaultRsrcName  'ics#' (kApplicationID);	// MacApp Family small black & white	include kDefaultRsrcName  'ics#' (kDocumentID);		// MacApp Document small black & whiteinclude kDefaultRsrcName  'ics#' (kStationeryID);	// MacApp Stationery small black & whiteinclude kDefaultRsrcName  'ics4' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics4' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics4' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'ics8' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics8' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics8' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'icl4' (kApplicationID);	// MacApp Family large 4 bitinclude kDefaultRsrcName  'icl4' (kDocumentID);		// MacApp Document large 4 bitinclude kDefaultRsrcName  'icl4' (kStationeryID);	// MacApp Stationery large 4 bitinclude kDefaultRsrcName  'icl8' (kApplicationID);	// MacApp Family large 8 bitinclude kDefaultRsrcName  'icl8' (kDocumentID);		// MacApp Document large 8 bitinclude kDefaultRsrcName  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit//--------------------------------------------------------------------------------------------------// Memory usage information for SimpleThreads//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	"SimpleThreads, "APPLE_LONG_COPYRIGHT};resource 'FREF' (kApplicationID,#if qNames"SimpleThreads Application",#endif	purgeable) {	'APPL',	0,	""};resource 'FREF' (kDocumentID,#if qNames"SimpleThreads Document",#endif	purgeable) {	kFileType,	1,	""};resource 'FREF' (kStationeryID,#if qNames"SimpleThreads Stationery",#endif	purgeable) {	kStationery,	2,	""};resource 'BNDL' (kBundleID,#if qNames"SimpleThreads",#endif	purgeable) {	kSignature,	0,	{ /* array TypeArray: 2 elements */		/* [1] */		'ICN#',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		},		/* [2] */		'FREF',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		}	}};resource 'open' (kBundleID){	kSignature, { kFileType, kStationery }};resource 'kind' (kBundleID){	kSignature,	verUS,	{		ftApplicationName, 	"SimpleThreads",		kFileType,			"SimpleThreads Document",		kStationery,		"SimpleThreads Stationery",	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x00,	development,	0x00,	verUs,	"1.0",	"SimpleThreads 1.0, "APPLE_LONG_COPYRIGHT};include kDefaultRsrcName  'vers' (2);		// Overall package